def assert_response(responseBody, globalParam, statusCode, headers):
    if not (statusCode == 200 and isinstance(responseBody, dict) and responseBody.get("code") == 0):
        raise Blocked("社区准备查询失败，无法取得注册前提")
    communities = responseBody.get("data")
    if not isinstance(communities, list) or not communities or not isinstance(communities[0], dict) or not communities[0].get("id"):
        raise Blocked("没有可用社区；无公开社区创建 HTTP 接口")
    raise Blocked("XSD rawBody 不支持动态参数；无法在超长昵称负向 JSON 中携带前序 HTTP 的社区 ID，目标注册及后续验证尚未执行")
